vec3 rgbToOklab(vec3 c) {
    // 1. Convertir de sRGB a RGB lineal
    vec3 linearRgb = srgbToLinear(c);
    vec3 lms = M1 * linearRgb;
    vec3 lmsCubed = pow(lms, vec3(1.0/3.0));
    return M2 * lmsCubed;
