vec3 oklabToRgb(vec3 c) {
    vec3 lmsCubed = INV_M2 * c;
    vec3 lms = pow(lmsCubed, vec3(3.0));
    vec3 linearRgb = INV_M1 * lms;

    return linearToSrgb(linearRgb);
}


